package com.example.assets_management.role.service;
import com.example.assets_management.company.entity.Company; import com.example.assets_management.company.repository.CompanyRepository; import com.example.assets_management.employee.repository.EmployeeRepository; import com.example.assets_management.role.dto.request.*; import com.example.assets_management.role.dto.response.RoleResponse; import com.example.assets_management.role.entity.Role; import com.example.assets_management.role.enums.*; import com.example.assets_management.role.repository.RoleRepository; import com.example.assets_management.security.context.CurrentUserService; import com.example.assets_management.security.rbac.audit.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class RoleServiceImpl implements RoleService { private final RoleRepository repo; private final CompanyRepository companies; private final CurrentUserService current; private final SecurityAuditService audit;
 private final EmployeeRepository employeeRepository;
 private final com.example.assets_management.role_permission.repository.RolePermissionRepository rolePermissions;
 public RoleServiceImpl(RoleRepository repo){this.repo=repo;this.companies=null;this.current=null;this.audit=null;this.employeeRepository=null;this.rolePermissions=null;}
 @org.springframework.beans.factory.annotation.Autowired public RoleServiceImpl(RoleRepository repo,CompanyRepository companies,CurrentUserService current,SecurityAuditService audit,EmployeeRepository employeeRepository,com.example.assets_management.role_permission.repository.RolePermissionRepository rolePermissions){this.repo=repo;this.companies=companies;this.current=current;this.audit=audit;this.employeeRepository=employeeRepository;this.rolePermissions=rolePermissions;}
 @Transactional(readOnly=true) public List<RoleResponse> getAll(){return (current==null||current.getCompanyId()==null?repo.findAll():repo.findByCompany_IdOrCompanyIsNull(current.getCompanyId())).stream().map(this::to).toList();} @Transactional(readOnly=true) public RoleResponse getById(UUID id){return to(get(id));}
 public RoleResponse createCustomRole(RoleCreateRequest r){validate(r.name(),r.code(),null); Role x=new Role();x.setName(r.name().trim());x.setCode(r.code().trim().toUpperCase());x.setDescription(r.description());x.setType(RoleType.CUSTOM);x.setStatus(RoleStatus.ACTIVE);x.setSystemDefined(false); Company c=null; if(current!=null&&companies!=null&&current.getCompanyId()!=null){c=companies.findById(current.getCompanyId()).orElseThrow(()->new IllegalStateException("Current company not found")); x.setCompany(c);} Role saved=repo.save(x); if(audit!=null&&current!=null)audit.record(c==null?null:c.getId(),current.requireUserId(),null,saved.getId(),null,SecurityAuditEventType.ROLE_CREATED,null,saved.getCode());return to(saved);}
 public RoleResponse updateCustomRole(UUID id,RoleUpdateRequest r){Role x=get(id);ensureCustom(x);validate(r.name(),r.code(),id);x.setName(r.name().trim());x.setCode(r.code().trim().toUpperCase());x.setDescription(r.description());Role saved=repo.save(x);audit.record(companyId(x),current.requireUserId(),null,x.getId(),null,SecurityAuditEventType.ROLE_UPDATED,null,saved.getCode());return to(saved);}
 public RoleResponse activate(UUID id){Role x=get(id);x.setStatus(RoleStatus.ACTIVE);return to(repo.save(x));} public RoleResponse deactivate(UUID id){Role x=get(id);if(com.example.assets_management.role.enums.SystemRole.isSuperAdmin(x))throw new IllegalStateException("The Super Admin role cannot be deactivated");x.setStatus(RoleStatus.INACTIVE);return to(repo.save(x));}
 public void deleteCustomRole(UUID id){Role x=get(id);ensureCustom(x);if(x.getId()!=null&&employeeCount(id)>0)throw new IllegalStateException("Role cannot be deleted while users are assigned");if(rolePermissions!=null){rolePermissions.deleteAll(rolePermissions.findByRole_Id(id));rolePermissions.flush();}repo.delete(x);}
 private long employeeCount(UUID id){return employeeRepository==null?0:employeeRepository.countByRole_Id(id); }
 private Role get(UUID id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Role not found: "+id));} private void ensureCustom(Role x){if(x.isSystemDefined()||x.getType()==RoleType.SYSTEM)throw new IllegalStateException("System-defined role cannot be modified or deleted"); if(current!=null&&x.getCompany()!=null&&!Objects.equals(x.getCompany().getId(),current.getCompanyId()))throw new IllegalStateException("Role belongs to another company");} private void validate(String n,String code,UUID id){repo.findAll().stream().filter(x->x.getName().equalsIgnoreCase(n.trim())||x.getCode().equalsIgnoreCase(code.trim())).filter(x->id==null||!x.getId().equals(id)).findFirst().ifPresent(x->{throw new IllegalStateException("Role name or code is already in use");});} private UUID companyId(Role x){return x.getCompany()==null?null:x.getCompany().getId();} private RoleResponse to(Role x){return new RoleResponse(x.getId(),companyId(x),x.getName(),x.getCode(),x.getDescription(),x.getType(),x.getStatus(),x.isSystemDefined(),x.isActive(),x.getCreatedAt(),x.getUpdatedAt());}}
